/////////////////////////
//~ yuraiz: Secondary definitions

//! This module contains the definitions of the various enums,
//! using types that can be statically defined without allocations

// AArch64 instruction definitions.
typedef struct DA64_InsnOperand DA64_InsnOperand;
struct DA64_InsnOperand {
    DA64_InsnOperandKind kind;
    DA64_InsnOperandClass class;
    DA64_InsnOperandQualifier* qualifiers;
    da64_u64 qualifier_count;
    DA64_BitfieldSpec* bit_fields;
    da64_u64 bit_field_count;
};

// AArch64 instruction definitions.
typedef struct DA64_Insn DA64_Insn;
struct DA64_Insn {
    char* mnemonic;
    da64_u64 mnemonic_size;
    DA64_Insn* aliases;
    da64_u64 alias_count;
    da64_u32 opcode;
    da64_u32 mask;
    DA64_InsnClass class;
    DA64_InsnFeatureSet feature_set;
    DA64_InsnOperand* operands;
    da64_u64 operand_count;
    DA64_InsnFlags flags;
};

